def update(self, pbar):
        """
        Handle progress bar updates
        @type   pbar:   ProgressBar
        @rtype: str
        """
        if pbar.label != self._label:
            self.label = pbar.label

        return self.label

def update(self, pbar):
        """
        Handle progress bar updates
        @type   pbar:   ProgressBar
        @rtype: str
        """
        if self.total is None:
            return
        if self.total == 0:
            return
        if self.total == 1:
            pbar.update(100)
            return
        if self.current == 0:
            pbar.update(0)
            return
        if self.current == self.total:
            pbar.update(100)
            return
        pbar.update(int(100 * self.current / self.total))

