        elif self.content_type == 'document':
            return self.default_document_sticker_id
        elif self.content_type == 'location':
            return self.default_location_sticker_id
        elif self.content_type == 'contact':
            return self.default_contact_sticker_id
        elif self.content_type == 'sticker':
