def _get_stddevs(self, coeffs, stddev_types):
        """
        Look up values from Table 5 on p. 483 and convert to natural logarithm.
        Interpretation of "sigma_log(Y)" as the common logarithm is based on
        the order of magnitude of the values and consistent use of "log" and
        "ln" to denote common and natural logarithm elsewhere in the paper.
        """
        stddevs = []
        for coeff, stddev_type in zip(coeffs, stddev_types):
            if stddev_type == "sigma_log(Y)":
                stddevs.append(np.log(coeff))
            elif stddev_type == "sigma_log(Y)**2":
                stddevs.append(np.log(coeff) ** 2)
            elif stddev_type == "sigma_log(Y)**3":
                stddevs.append(np.log(coeff) ** 3)
            elif stddev_type == "sigma_log(Y)**4":
                stddevs.append(np.log(coeff) ** 4)
            elif stddev_type == "sigma_log(Y)**5":
                stddevs.append(np.log(coeff) ** 5)
            elif stddev_type == "sigma_log(Y)**6":
                stddevs.append(np.log(coeff) ** 6)
            elif stddev_type == "sigma_log(Y)**7":
                stddevs.append(np.log(coeff) ** 7)
            elif stddev_type == "sigma_log(Y)**8":
                stddevs.append(np.log(coeff) ** 8)
            elif stddev_type == "sigma_log(Y)**9":
                stddevs.append(np.log(coeff) ** 9)
            elif stddev_type == "sigma_log(Y)**10":
                stddevs.append(np.log(coeff) ** 10)
            elif stddev_type == "sigma_log(Y)**11":
                stddevs.append(np.log(coeff) ** 11)
            elif stddev_type == "sigma_log(Y)**12":
                stddevs.append(np.log(coeff) ** 12)
            elif stddev_type == "sigma_log(Y)**13":
                stddevs.append(np.log(coeff) ** 13)

