        else:
            shutil.copyfile(path + '.bak', path)

def accumulate(self, axis: AxisIdentifier) -> HistogramBase:
        """Calculate cumulative frequencies along a certain axis.

        Returns
        -------
        new_hist: Histogram of the same type & size
        """
        if axis == Axis.CHANNEL:
            return self.accumulate_channel()
        elif axis == Axis.BIN:
            return self.accumulate_bin()
        elif axis == Axis.X:
            return self.accumulate_x()
        elif axis == Axis.Y:
            return self.accumulate_y()
        elif axis == Axis.Z:
            return self.accumulate_z()
        else:
            raise ValueError(f"Unknown axis {axis}")

def local_rfcformat(dt):
    """Return the RFC822-formatted representation of a timezone-aware datetime
    with the UTC offset.
    """
    if dt.tzinfo is None:
        raise ValueError("datetime must be timezone-aware")
    return dt.strftime("%a, %d %b %Y %H:%M:%S %z")

def write_to_file(self, destination_path):
        """
        Writes the metadata json or xml to a file.

        :param destination_path: the file path the file format is inferred
        from the destination_path extension.
        :type destination_path: str
        :return: the written metadata
        :rtype: str
        """
        if destination_path.endswith(".json"):
            return self.write_to_json(destination_path)
        elif destination_path.endswith(".xml"):
            return self.write_to_xml(destination_path)
        else:
            raise ValueError("Invalid file extension. Must be .json or .xml")

def get_unpatched_class(cls):
    """Protect against re-patching the distutils if reloaded

    Also ensures that no other distutils extension monkeypatched the distutils
    first.
    """
    external_bases = (
        cls
        for cls in _get_mro(cls)
        if not cls.__module__.startswith('setuptools')
    )
    base = next(external_bases)
    if not base.__module__.startswith('distutils'):
        msg = "distutils has already been patched by %r" % cls
        raise AssertionError(msg)
    return base

def _connection(self):
        """
        If we have a pipeline, shared in thread, or in the good thread, return it
        else use the direct connection
        """
        if self.pipeline:
            return self.pipeline
        elif self.shared_connection:
            return self.shared_connection
        elif self.connection:
            return self.connection
        else:
            return self.direct_connection

def _associate_placeable(self, location):
        """
        Saves a reference to a placeable
        """
        if not location:
            return

        placeable, _ = unpack_location(location)
        self.previous_placeable = placeable
        if not self.placeables or (placeable != self.placeables[-1]):
            self.placeables.append(placeable)

def same(d1, d2):
    """! @brief Test whether two sequences contain the same values.

    Unlike a simple equality comparison, this function works as expected when the two sequences
    are of different types, such as a list and bytearray. The sequences must return
    compatible types from indexing.
    """
    if len(d1) != len(d2):
        return False
    for i in range(len(d1)):
        if d1[i] != d2[i]:
            return False
    return True

def same(d1, d2):
