def moving_average(data, periods, type='simple'):
    """
    compute a <periods> period moving average.
    type is 'simple' | 'exponential'
    """
    if type == 'simple':
        return data.rolling(periods).mean()
    elif type == 'exponential':
        return data.ewm(span=periods).mean()
    else:
        raise ValueError('type must be "simple" or "exponential"')

def parse_ast(source, filename=None):
    """Parse source into a Python AST, taking care of encoding."""
    if isinstance(source, text_type) and sys.version_info[0] == 2:
        # ast.parse() on Python 2 doesn't like encoding declarations
        # in Unicode strings
        source = CODING_COOKIE_RE.sub(r'\1', source, 1)
    return ast.parse(source, filename or '<unknown>')

def parse_ast(source, filename=None):
    """Parse source into a Python AST, taking care of encoding."""
    if filename is None:
        filename = '<string>'
    encoding = 'utf-8'
    if isinstance(source, bytes):
        source = source.decode(encoding)
    try:
        return ast.parse(source, filename=filename)
    except SyntaxError:
        # Compare the line number reported by the SyntaxError with the last
        # line containing a non-ASCII character in the string. If they differ,
        # it's a false positive caused by an encoding error in the source.
        # In that case, re-raise the exception with the correct line number.
        line_with_non_ascii = source.rstrip().rfind('\n')
        if line_with_non_ascii != -1:
            last_line = source.splitlines()[line_with_non_ascii]
            non_ascii_bytes = last_line.encode(encoding)
            non_ascii_chars = non_ascii_bytes.decode(encoding, 'ignore')
            if len(non_ascii_chars) < len(last_line):
                syntax_error = sys.exc_info()[1]
                syntax_error.lineno = syntax_error.lineno + (
                    len(last_line) - len(non_ascii_chars))
                raise syntax_error
        raise

