def parse_schema_definition(lexer: Lexer) -> SchemaDefinitionNode:
    """SchemaDefinition"""
    start = lexer.token
    expect_keyword(lexer, "schema")
    directives = parse_directives(lexer, True)
    operation_types = many_nodes(
        lexer, TokenKind.BRACE_L, parse_operation_type_definition, TokenKind.BRACE_R
    )
    return SchemaDefinitionNode(
        directives=directives, operation_types=operation_types, loc=loc(lexer, start)
    )

def timemeter(msg=None):
    """Timer meter

        Use this annotation method can calculate the execute time.
    :param msg: custom message output
    :return: fn values
    """
    def _time_meter(fn):
        @functools.wraps(fn)
        def _wrapper(*args, **kwargs):
            mark = timeit.default_timer()
            result = fn(*args, **kwargs)
            cost = timeit.default_timer() - mark
            if msg:
                logger.info(msg, cost)
            else:
                logger.info('Execute <%s.%s> method cost %s seconds.', fn.__module__, fn.__name__, cost)
            return result
        return _wrapper
    return _time_meter

def timemeter(msg=None):
    """Timer meter

        Use this annotation method can calculate the execute time.
    :param msg: custom message output
    :return: fn values
    """

    def decorator(fn):
        def wrapper(*args, **kwargs):
            start = time.time()
            result = fn(*args, **kwargs)
            end = time.time()
            if msg is None:
                print(f"{fn.__name__} execute time: {end - start}s")
            else:
                print(f"{msg} execute time: {end - start}s")
            return result

        return wrapper

    return decorator

def create_files(filedef, cleanup=True):
    """Contextmanager that creates a directory structure from a yaml
       descripttion.
    """
    import os
    import shutil
    import tempfile
    import yaml

    def _create_files(filedef):
        """Create the files and directories described in the filedef.
        """
        for name, contents in filedef.items():
            if isinstance(contents, dict):
                os.mkdir(name)
                _create_files(contents)
            else:
                with open(name, 'w') as f:
                    f.write(contents)

    def _cleanup(filedef):
        """Remove the files and directories described in the filedef.
        """
        for name, contents in filedef.items():
            if isinstance(contents, dict):
                _cleanup(contents)
                os.rmdir(name)
            else:
                os.remove(name)

    tmpdir = tempfile.mkdtemp()
    try:
        _create_files(filedef)
        yield tmpdir
    finally:
        if cleanup:
            _cleanup(filedef)
        shutil.rmtree(tmpdir)

def _update_dict(self, to_dict, from_dict):
        """ Recursively merges the fields for two dictionaries.

        Args:
            to_dict (dict): The dictionary onto which the merge is executed.
            from_dict (dict): The dictionary merged into to_dict
        """
        for key, value in from_dict.items():
            if isinstance(value, dict):
                to_dict[key] = _update_dict(to_dict.get(key, {}), value)
            else:
                to_dict[key] = value

def __store_config(self, args, kwargs):
        """ Assign args to kwargs and store configuration. """
        signature = (
            'schema',
            'ignore_none_values',
            'allow_unknown',
            'require_all',
            'purge_unknown',
            'purge_readonly',
        )
        for i, p in enumerate(signature[: len(args)]):
            if p in kwargs:
                raise TypeError("__init__ got multiple values for argument " "'%s'" % p)
            else:
                kwargs[p] = args[i]
        self._config = kwargs

def __store_config(self, args, kwargs):
        """ Assign args to kwargs and store configuration. """
        for arg in args:
            kwargs[arg] = getattr(self, arg)
        self.config = kwargs

