def from_dict(d):
    """
    load an nparray object from a dictionary

    @parameter str d: dictionary representing the nparray object
    """
    if isinstance(d, str):
        return from_json(d)

    if not isinstance(d, dict):
        raise TypeError("argument must be of type dict")
    if 'nparray' not in d.keys():
        raise ValueError("input dictionary missing 'nparray' entry")

    classname = d.pop('nparray').title()
    return getattr(_wrappers, classname)(**d)

def from_dict(d):
    """
    load an nparray object from a dictionary

    @parameter str d: dictionary representing the nparray object
    """
    return np.array(d['data'], dtype=d['dtype'])

def parse_config_list(config_list):
  """
  Parse a list of configuration properties separated by '='
  """
  if config_list is None:
    return {}
  else:
    mapping = {}
    for pair in config_list:
      if (constants.CONFIG_SEPARATOR not in pair) or (pair.count(constants.CONFIG_SEPARATOR) != 1):
        raise ValueError("configs must be passed as two strings separted by a %s", constants.CONFIG_SEPARATOR)
      (config, value) = pair.split(constants.CONFIG_SEPARATOR)
      mapping[config] = value
    return mapping

def parse_config_list(config_list):
  """
  Parse a list of configuration properties separated by '='
  """
  config_dict = {}
  for config_item in config_list:
    config_key, config_value = config_item.split('=')
    config_dict[config_key] = config_value
  return config_dict

def _validI(x, y, weights):
    """
    return indices that have enough data points and are not erroneous 
    """
    if x.shape[0] < 3:
        return np.array([], dtype=int)
    if np.isnan(x).any() or np.isnan(y).any():
        return np.array([], dtype=int)
    if np.isinf(x).any() or np.isinf(y).any():
        return np.array([], dtype=int)
    if np.isneginf(x).any() or np.isneginf(y).any():
        return np.array([], dtype=int)
    if np.isposinf(x).any() or np.isposinf(y).any():
        return np.array([], dtype=int)
    if np.isneginf(weights).any() or np.isposinf(weights).any():
        return np.array([], dtype=int)
    if np.isnan(weights).any():
        return np.array([], dtype=int)
    if np.isinf(weights).any():
        return np.array([], dtype=int)
    if np.isneginf(weights).any():
        return np.array([], dtype=int)
    if np.isposinf(weights).any():
        return np.array([], dtype=int)
    if np.isneginf(weights).any():
        return np.array([], dtype=int)
    if np.isposinf(weights).any():
        return np.array([], dtype=int)
    if np.isnan(weights).any():
        return np.array([], dtype=int)
    if np.isinf(weights).any():
        return np.array([], dtype=int)
    if np.isneginf(weights).any():
        return np.array([], dtype=int)
    if np.isposinf(weights).any():
        return np.array([], dtype=int)
    if np.isneginf(weights).any():
        return np.array([], dtype=int)
    if np.isposinf(weights).any():
        return np.array

def __find_rows(self, find_url, **attributes):
        """
            :param find_url: URL of the find api
            :type find_url: string
            :return: The Response returned by requests including the list of documents based on find_url
            :rtype: Response object
        """
        req = self.url + find_url

        # Add range and sort parameters
        params = {
            "range": attributes.get("range", "all"),
            "sort": attributes.get("sort", [])
        }

        # Add body
        data = {
            "query": attributes.get("query", {})
        }

        try:
            return requests.post(req, params=params, json=data, proxies=self.proxies, auth=self.auth, verify=self.cert)
        except requests.exceptions.RequestException as e:
            raise TheHiveException("Error: {}".format(e))

def _temp_bool_prop(propname, doc="", default=False):
    """Creates a property that uses the :class:`_TempBool` class

    Parameters
    ----------
    propname: str
        The attribute name to use. The _TempBool instance will be stored in the
        ``'_' + propname`` attribute of the corresponding instance
    doc: str
        The documentation of the property
    default: bool
        The default value of the _TempBool class"""
    def getx(self):
        if getattr(self, '_' + propname, None) is not None:
            return getattr(self, '_' + propname)
        else:
            setattr(self, '_' + propname, _TempBool(default))
        return getattr(self, '_' + propname)

    def setx(self, value):
        getattr(self, propname).value = bool(value)

    def delx(self):
        getattr(self, propname).value = default

    return property(getx, setx, delx, doc)

def get_visible_items(self):
        """Return a list of all visible items in the treewidget."""
        items = []
        iterator = QTreeWidgetItemIterator(self)
        while iterator.value():
            item = iterator.value()
            if not item.isHidden():
                if item.parent():
                    if item.parent().isExpanded():
                        items.append(item)
                else:
                    items.append(item)
            iterator += 1
        return items

def get_visible_items(self):
        """Return a list of all visible items in the treewidget."""
        return [item for item in self.get_items() if item.isVisible()]

def GET_namespace_num_names(self, path_info, namespace_id):
        """
        Get the number of names in a namespace
        Reply the number on success
        Reply 404 if the namespace does not exist
        Reply 502 on failure to talk to the blockstack server
        """
        if not check_namespace(namespace_id):
            return self._reply_json({'error': 'Invalid namespace'}, status_code=400)

        blockstackd_url = get_blockstackd_url()
        name_count = blockstackd_client.get_num_names_in_namespace(namespace_id, hostport=blockstackd_url)
        if json_is_error(name_count):
            log.error("Failed to load namespace count for {}: {}".format(namespace_id, name_count['error']))
            return self._reply_json({'error': 'Failed to load namespace count: {}'.format(name_count['error'])}, status_code=404)

        self._reply_json({'names_count': name_count})

def cmp(self,range2,overlap_size=0):
    """the comparitor for ranges

     * return 1 if greater than range2
     * return -1 if less than range2
     * return 0 if overlapped

    :param range2:
    :param overlap_size: allow some padding for an 'equal' comparison (default 0)
    :type range2: GenomicRange
    :type overlap_size: int

    """
    if self.chrom != range2.chrom:
        return 1 if self.chrom > range2.chrom else -1
    if self.start > range2.start:
        return 1
    if self.start < range2.start:
        return -1
    if self.end > range2.end:
        return 1
    if self.end < range2.end:
        return -1
    if self.end - self.start + overlap_size < range2.end - range2.start + overlap_size:
        return 1
    if self.end - self.start + overlap_size > range2.end - range2.start + overlap_size:
        return -1
    return 0

