def get_pks_for_filter(self, key, filter_type, value):
        """Extract the pks from the zset key for the given type and value

        For the parameters, see BaseRangeIndex.get_pks_for_filter
        """
        if filter_type == 'gt':
            return self.zrangebyscore(key, value, '+inf')
        elif filter_type == 'gte':
            return self.zrangebyscore(key, value, '+inf', withscores=True)
        elif filter_type == 'lt':
            return self.zrangebyscore(key, '-inf', value)
        elif filter_type == 'lte':
            return self.zrangebyscore(key, '-inf', value, withscores=True)
        elif filter_type == 'eq':
            return self.zrangebyscore(key, value, value)
        elif filter_type == 'ne':
            return self.zrangebyscore(key, '-inf', '+inf')
        elif filter_type == 'in':
            return self.zrangebyscore(key, *value)
        elif filter_type == 'nin':
            return self.zrangebyscore(key, '-inf', '+inf')
        else:
            raise ValueError('Invalid filter type: %s' % filter_type)

def _set_instance_ip(self):
        """
        Get the IP address based on instance ID.

        If public IP address not found attempt to get private IP.
        """
        try:
            ip_address = self.network.public_ip_addresses.get(
                self.running_instance_id, self.public_ip_name
            ).ip_address
        except Exception:
            try:
                ip_address = self.network.network_interfaces.get(
                    self.running_instance_id, self.nic_name
                ).ip_configurations[0].private_ip_address
            except Exception as error:
                raise AzureCloudException(
                    'Unable to retrieve instance IP address: {0}.'.format(
                        error
                    )
                )

        self.instance_ip = ip_address

def _set_instance_ip(self):
        """
        Get the IP address based on instance ID.

        If public IP address not found attempt to get private IP.
        """
        try:
            self.instance_ip = self.ec2_client.describe_instances(
                InstanceIds=[self.instance_id]
            )['Reservations'][0]['Instances'][0]['PublicIpAddress']
        except KeyError:
            self.instance_ip = self.ec2_client.describe_instances(
                InstanceIds=[self.instance_id]
            )['Reservations'][0]['Instances'][0]['PrivateIpAddress']

def resolve_service_spec(self, name, lineno):
        """Finds and links the ServiceSpec with the given name."""

        if name in self.service_specs:
            return self.service_specs[name].link(self)

        if '.' in name:
            include_name, component = name.split('.', 2)
            if include_name in self.included_scopes:
                return self.included_scopes[
                    include_name
                ].resolve_service_spec(component, lineno)

        raise ThriftCompilerError(
            'Unknown service "%s" referenced at line %d%s' % (
                name, lineno, self.__in_path()
            )
        )

def resolve_service_spec(self, name, lineno):
        """Finds and links the ServiceSpec with the given name."""
        if name in self.service_specs:
            return self.service_specs[name]
        else:
            raise ParseError(
                "ServiceSpec %r not found" % name,
                self.filename, lineno)

def clean_text(self, domain, **kwargs):
        """Try to extract only the domain bit from the """
        if domain is None:
            return None
        if domain.startswith('http://'):
            domain = domain[7:]
        if domain.startswith('https://'):
            domain = domain[8:]
        if domain.startswith('www.'):
            domain = domain[4:]
        if domain.endswith('/'):
            domain = domain[:-1]
        return domain

def get_translation(self, lang, field):
        """
        Return the translation string of an specific field in a Translatable
        istance

        @type lang: string
        @param lang: a string with the name of the language

        @type field: string
        @param field: a string with the name that we try to get

        @rtype: string
        @return: Returns a translation string
        """
        # Read from cache
        key = self._get_translation_cache_key(lang, field)
        trans = cache.get(key, '')

        if not trans:
            trans_obj = self.get_translation_obj(lang, field)
            trans = getattr(trans_obj, 'translation', '')
            # if there's no translation text fall back to the model field
            if not trans:
                trans = getattr(self, field, '')
            # update cache
            cache.set(key, trans)
        return trans

def get_translation(self, lang, field):
        """
        Return the translation string of an specific field in a Translatable
        istance

        @type lang: string
        @param lang: a string with the name of the language

        @type field: string
        @param field: a string with the name that we try to get

        @rtype: string
        @return: Returns a translation string
        """
        if field in self.translations:
            if lang in self.translations[field]:
                return self.translations[field][lang]
            else:
                return self.translations[field]['en']
        else:
            return None

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        for schema in schemas:
            if schema == os.path.abspath(schema):
                schema_file = schema
            else:
                schema_file = os.path.join(self.paths.schemas, schema)

            if os.path.isfile(schema_file):
                # Absolute path: use it.
                yield schema_file
            elif skip_missing_schemas:
                logger.warning("Unable to locate schema %s at %s", schema, schema_file)
            else:
                raise PathError("Unable to locate schema %s at %s" % (schema, schema_file))

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        for schema in schemas:
            if schema not in self.schemas:
                if skip_missing_schemas:
                    continue
                raise ldaperrors.NoSuchObject(
                    "No such schema: %s" % schema)

