def _normalize_sort_SQL(self, field_name, field_vals, sort_dir_str):
        """
        allow sorting by a set of values

        http://stackoverflow.com/questions/3303851/sqlite-and-custom-order-by
        """
        if sort_dir_str == 'desc':
            sort_dir_str = 'desc'
        else:
            sort_dir_str = 'asc'

        if field_name == 'id':
            field_name = 'id'
        else:
            field_name = 'name'

        if field_vals == 'all':
            field_vals = 'all'
        else:
            field_vals = '(' + ','.join(field_vals) + ')'

        return ' '.join([field_name, field_vals, sort_dir_str])

def get_type(full_path):
    """Get the type (socket, file, dir, symlink, ...) for the provided path"""
    status = {'type': []}
    if os.path.ismount(full_path):
        status['type'] += ['mount-point']
    elif os.path.islink(full_path):
        status['type'] += ['symlink']
    if os.path.isfile(full_path):
        status['type'] += ['file']
    elif os.path.isdir(full_path):
        status['type'] += ['dir']
    if not status['type']:
        if os.stat.S_ISSOCK(status['mode']):
            status['type'] += ['socket']
        elif os.stat.S_ISCHR(status['mode']):
            status['type'] += ['special']
        elif os.stat.S_ISBLK(status['mode']):
            status['type'] += ['block-device']
        elif os.stat.S_ISFIFO(status['mode']):
            status['type'] += ['pipe']
    if not status['type']:
        status['type'] += ['unknown']
    elif status['type'] and status['type'][-1] == 'symlink':
        status['type'] += ['broken']
    return status['type']

def get_type(full_path):
    """Get the type (socket, file, dir, symlink, ...) for the provided path"""
    if os.path.isdir(full_path):
        return 'dir'
    elif os.path.isfile(full_path):
        return 'file'
    elif os.path.islink(full_path):
        return 'symlink'
    elif os.path.ismount(full_path):
        return 'mount'
    elif os.path.issocket(full_path):
        return 'socket'
    elif os.path.isblockdev(full_path):
        return 'blockdev'
    elif os.path.ischardev(full_path):
        return 'chardev'
    else:
        return 'unknown'

def _validate_indexers(self, key):
        """ Make sanity checks """
        for dim, k in zip(self.dims, key):
            if isinstance(k, BASIC_INDEXING_TYPES):
                pass
            else:
                if not isinstance(k, Variable):
                    k = np.asarray(k)
                    if k.ndim > 1:
                        raise IndexError(
                            "Unlabeled multi-dimensional array cannot be "
                            "used for indexing: {}".format(k))
                if k.dtype.kind == 'b':
                    if self.shape[self.get_axis_num(dim)] != len(k):
                        raise IndexError(
                            "Boolean array size {0:d} is used to index array "
                            "with shape {1:s}.".format(len(k),
                                                       str(self.shape)))
                    if k.ndim > 1:
                        raise IndexError("{}-dimensional boolean indexing is "
                                         "not supported. ".format(k.ndim))
                    if getattr(k, 'dims', (dim, )) != (dim, ):
                        raise IndexError(
                            "Boolean indexer should be unlabeled or on the "
                            "same dimension to the indexed array. Indexer is "
                            "on {0:s} but the target dimension is "
                            "{1:s}.".format(str(k.dims), dim))

def _validate_indexers(self, key):
        """ Make sanity checks """
        if not isinstance(key, tuple):
            raise TypeError("key must be a tuple")
        if len(key) != self.ndim:
            raise ValueError("key must be of length %d" % self.ndim)
        for i, k in enumerate(key):
            if not isinstance(k, slice):
                raise TypeError("key[%d] must be a slice" % i)

def fetch(self, _filter=None, ignore_incremental=False):
        """ Fetch the items from raw or enriched index. An optional _filter
        could be provided to filter the data collected """
        if self.raw_index:
            return self.fetch_from_raw_index(_filter, ignore_incremental)
        else:
            return self.fetch_from_enriched_index(_filter, ignore_incremental)

